<?php
/** Plain-language SEO health and AI search readiness. GPL-3.0-or-later, 2026-11-16. */
namespace OpenSEO;
defined('ABSPATH') || exit;
final class HealthAdmin {
    public static function url($id=0){return add_query_arg(array_filter(['page'=>'open-seo-health','post'=>$id?:null]),admin_url('admin.php'));}
    public static function form($operation,$id=0){echo'<form class="'.($operation==='review-meta'?'open-seo-review-form':'open-seo-action-form').'" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="open_seo_health"><input type="hidden" name="operation" value="'.esc_attr($operation).'"><input type="hidden" name="id" value="'.(int)$id.'">';wp_nonce_field('open_seo_health');}
    public static function button($op,$text,$id=0,$primary=false){self::form($op,$id);echo'<button class="button '.($primary?'button-primary':'button-secondary').'" type="submit">'.esc_html($text).'</button></form>';}
    public static function handle(){
        guard();check_admin_referer('open_seo_health');$op=sanitize_key(wp_unslash($_POST['operation']??''));$id=absint($_POST['id']??0);
        try{
            if($op==='scan'){HealthJobs::start('scan');Suite::notice('Website scan started. Keep this page open for live progress, or let WordPress cron continue in the background.');$id=0;}
            elseif($op==='fix-all'){HealthJobs::start('fix');Suite::notice('Safe-fix job started for scanned pages. Existing written fields and page-builder content are preserved. Scan again after completion to verify the published output.');$id=0;}
            elseif($op==='stop'){$job=get_option('open_seo_health_job',[]);$job['status']='stopped';update_option('open_seo_health_job',$job,false);wp_clear_scheduled_hook('open_seo_health_batch');Suite::notice('Stopped after any currently running page.');}
            elseif(in_array($op,['scan-page','fix-page'],true)){if(!current_user_can('edit_post',$id)||!Health::allowed(get_post($id)))throw new \RuntimeException('Select a public, published page you can edit.');if($op==='scan-page'){Health::scan_post($id);Suite::notice('Published page checked. Review unverified items as well as warnings.');}else{$changes=Health::fix($id);Suite::notice($changes.' empty fields or alt-inheritance settings updated. Written text is preserved. Re-scan to verify output; clear page cache if the published page still shows old values.');}}
            elseif($op==='review-meta'){
                $key=sanitize_key(wp_unslash($_POST['plan']??''));$plan=get_transient('open_seo_health_plan_'.get_current_user_id().'_'.$key);
                if(!$plan||$plan['id']!==$id)throw new \RuntimeException('Review expired. Open the report again.');
                $row=$plan['row'];foreach(['title'=>'rank_math_title','description'=>'rank_math_description','keywords'=>'rank_math_focus_keyword']as$field=>$meta){$row['after'][$meta]=sanitize_text_field(wp_unslash($_POST[$field]??''));}
                Bulk::apply([$row]);set_transient('open_seo_health_undo_'.get_current_user_id(),[$row],DAY_IN_SECONDS);delete_transient('open_seo_health_plan_'.get_current_user_id().'_'.$key);Suite::notice('Your reviewed SEO fields were saved. Page content was not rewritten. Re-scan to verify the published output.');
            }elseif($op==='undo'){$rows=get_transient('open_seo_health_undo_'.get_current_user_id());if(!$rows)throw new \RuntimeException('No current metadata undo.');Bulk::apply($rows,true);delete_transient('open_seo_health_undo_'.get_current_user_id());Suite::notice('Reviewed SEO fields restored.');}
            else{throw new \RuntimeException('Unknown health action.');}
        }catch(\Throwable$error){Suite::notice($error->getMessage());}
        wp_safe_redirect(self::url($id));exit;
    }
    public static function checklist($checks){echo'<ul class="open-seo-checklist">';foreach($checks as$check){$label=$check['state']==='pass'?'Checked':($check['state']==='unknown'?'Not verified':($check['action']==='safe'?'Fix automatically':'Needs review'));echo'<li class="open-seo-check open-seo-check-'.esc_attr($check['state']).'"><strong>'.esc_html($label.' · '.$check['title']).'</strong><p>'.esc_html($check['detail']).'</p></li>';}echo'</ul>';}
    public static function counts($report){$totals=['pass'=>0,'review'=>0,'safe'=>0,'unknown'=>0];foreach($report['checks']as$c){$totals[$c['state']]++;if($c['state']==='review'&&$c['action']==='safe')$totals['safe']++;}return$totals;}
    public static function review_form($post){
        if(!current_user_can('edit_post',$post->ID))return;
        $cached=get_post_meta($post->ID,Health::SOURCE,true);if(Health::builder($post)&&(!is_array($cached)||($cached['fingerprint']??'')!==Health::fingerprint($post)||time()-($cached['at']??0)>=DAY_IN_SECONDS)){echo'<p>Re-scan this builder page before reviewing content-based suggestions.</p>';return;}
        $clone=clone$post;$clone->post_content=Health::source($post->post_content,$post);$proposed=Automation::suggestions($clone);$before=[];$exists=[];
        foreach(['rank_math_title','rank_math_description','rank_math_focus_keyword']as$key){$before[$key]=get_post_meta($post->ID,$key,true);$exists[$key]=metadata_exists('post',$post->ID,$key);}
        $keyword=trim(explode(',',(string)$before['rank_math_focus_keyword'])[0]);
        if($before['rank_math_focus_keyword']!==''){$proposed['rank_math_focus_keyword']=$before['rank_math_focus_keyword'];}
        if($keyword){$heading=is_array($cached)?($cached['heading']??''):'';$proposed['rank_math_title']=Health::occurrences($heading,$keyword)?$heading:ucfirst($keyword);$name=get_bloginfo('name');if($name&&stripos($proposed['rank_math_title'],$name)===false){$proposed['rank_math_title'].=' | '.$name;}
            $dom=Links::document($clone->post_content);foreach($dom->getElementsByTagName('p')as$p){$text=trim($p->textContent);if(!Health::occurrences($text,$keyword))continue;foreach(preg_split('/(?<=[.!?])\s+/u',$text)as$sentence){if(Health::occurrences($sentence,$keyword)&&strlen($sentence)>=30){$proposed['rank_math_description']=wp_html_excerpt($sentence,160,'');break 2;}}}
        }
        $token=strtolower(wp_generate_password(20,false,false));$row=['id'=>$post->ID,'before'=>$before,'exists'=>$exists,'after'=>$proposed];set_transient('open_seo_health_plan_'.get_current_user_id().'_'.$token,['id'=>$post->ID,'row'=>$row],600);
        echo'<details><summary>Review suggested SEO text before changing written fields</summary><p>Current values are shown for comparison. Edit the suggestions, then apply only if they accurately describe this page. This replaces the three SEO fields explicitly; it never changes the page body.</p>';
        self::form('review-meta',$post->ID);echo'<input type="hidden" name="plan" value="'.esc_attr($token).'">';
        foreach(['title'=>'rank_math_title','description'=>'rank_math_description','keywords'=>'rank_math_focus_keyword']as$field=>$key){echo'<div class="open-seo-review-field"><p class="open-seo-current"><strong>Current '.esc_html($field).':</strong> '.esc_html($before[$key]?:'(empty)').'</p><label for="health-'.$field.'-'.(int)$post->ID.'">Suggested '.esc_html($field).'</label><textarea class="large-text" rows="'.($field==='description'?4:2).'" id="health-'.$field.'-'.(int)$post->ID.'" name="'.esc_attr($field).'">'.esc_textarea($proposed[$key]).'</textarea></div>';}
        echo'<button type="submit" class="button button-secondary">Apply reviewed SEO fields</button></form></details>';
    }
    public static function report($post,$report){
        $totals=self::counts($report);echo'<article class="postbox open-seo-report"><h2>'.esc_html($post->post_title).'</h2><p><a href="'.esc_url($report['url']).'" target="_blank" rel="noopener">View published page</a> · <a href="'.esc_url(get_edit_post_link($post->ID)).'">Edit page'.($report['builder']?' in its builder':'').'</a></p><p class="open-seo-report-source">'.esc_html($report['source'].' · '.$report['at']).'</p><p class="open-seo-report-totals"><strong>'.$totals['safe'].' fixable checks · '.$totals['review'].' total reviews · '.$totals['unknown'].' unverified · '.$totals['pass'].' checked</strong></p>';
        if($report['builder']){echo'<p><strong>'.esc_html($report['builder']).' detected.</strong> The scan reads published HTML. An unsupported-block warning or another open Oxygen editor is a separate builder issue; do not remove the block or force-unlock another person’s work to chase an SEO score.</p>';}
        if($report['editor_score']!==''){echo'<p>Saved editor checklist score: '.esc_html($report['editor_score']).'/100. This report does not overwrite that number. Real fixes may change it after the editor refreshes.</p>';}
        self::button('fix-page','Fix safe issues on this page',$post->ID);self::button('scan-page','Re-scan published page',$post->ID);
        echo'<details open><summary>SEO issues and next steps</summary>';self::checklist($report['checks']);echo'</details><details><summary>AI search readiness — what GEO means for this page</summary><p>Help AI search systems read the page and understand its answers and facts. These checks do not guarantee a citation.</p>';self::checklist($report['ai']);echo'</details>';
        if($report['repeated']){echo'<details><summary>Passages to review for repetition</summary><p>Use fewer repeated phrases only where the text becomes more natural. Google does not prescribe one ideal keyword percentage.</p>';foreach($report['repeated']as$passage){echo'<blockquote><p>'.esc_html($passage['text']).'</p><p>'.(int)$passage['count'].' exact phrase matches in this paragraph.</p></blockquote>';}echo'</details>';}
        self::review_form($post);echo'</article>';
    }
    public static function page(){
        guard();$id=absint($_GET['post']??0);echo'<div class="wrap open-seo-admin"><h1>SEO Health & Fixes</h1><p class="open-seo-lead">Find problems on published pages, fix missing information, and review wording that needs your judgment.</p><nav class="open-seo-page-links" aria-label="Open SEO tools"><span aria-current="page">SEO Health & Fixes</span><span aria-hidden="true"> / </span><a href="'.esc_url(SharedContentAdmin::url()).'">GEO Website Info</a></nav><p>Safe fixes fill blank SEO fields and reuse image descriptions already written in your media library. They do not rewrite your page, change your chosen keyword, remove noindex or unlock Oxygen.</p>';SuiteAdmin::messages();
        echo'<div class="notice notice-info inline"><p><strong>About the 100-point editor score:</strong> it is a plugin checklist, not a Google ranking. This tool fixes real issues and reports the checks it could verify; it never forces a score to 100. Keyword placement and repetition need natural wording, especially on builder pages.</p></div>';
        self::button('scan','Scan website',0,true);self::button('fix-all','Fix safe issues on scanned pages');
        $job=get_option('open_seo_health_job',[]);if(($job['status']??'')==='running'){self::button('stop','Stop background job');}
        echo'<div id="open-seo-health-progress" role="status" aria-live="polite">';if($job){echo esc_html(ucfirst($job['kind']).' job: '.$job['status'].' · '.$job['processed'].' pages processed · '.$job['changed'].' field/settings changes. '.($job['message']??''));}else{echo'No scan yet. Start with Scan website.';}echo'</div>';
        echo'<details style="margin:16px 0"><summary>What is GEO? Explain AI search readiness</summary><p>GEO means Generative Engine Optimization: helping AI-assisted search understand and potentially cite useful content. Start with the same foundations as SEO: accessible pages, clear answers, accurate facts, real sources and relevant structured data. There is no special tag or guaranteed AI ranking.</p><ol><li>Make the page readable to search crawlers.</li><li>Give a clear answer near the beginning.</li><li>Show who is responsible and keep facts consistent.</li><li>Use relevant schema and visible FAQs where they help readers.</li></ol><p>Use the AI search readiness section inside each page report. Advanced crawler controls remain under AI Search & Console.</p></details>';
        $site=get_option('open_seo_health_site',[]);if($site){echo'<details><summary>Website-wide crawl and sitemap checks</summary>';self::checklist($site['checks']);echo'</details>';}
        $duplicates=get_option('open_seo_health_duplicates',[]);if($duplicates){echo'<details><summary>Repeated titles or descriptions across pages</summary><p>Review whether these pages need distinct descriptions. Some duplicates are intentional. Up to 50 groups and 10 links per group are shown.</p><ul>';foreach($duplicates as$group){echo'<li><strong>'.(int)$group['count'].' pages share a rendered '.esc_html($group['field']).':</strong> ';foreach($group['ids']as$duplicateId){echo'<a href="'.esc_url(self::url($duplicateId)).'">'.esc_html(get_the_title($duplicateId)).'</a> ';}echo'</li>';}echo'</ul></details>';}
        if(get_transient('open_seo_health_undo_'.get_current_user_id())){self::button('undo','Undo last reviewed metadata edit');}
        $paged=max(1,absint($_GET['paged']??1));$args=['post_type'=>Health::types(),'post_status'=>'publish','has_password'=>false,'posts_per_page'=>10,'paged'=>$paged,'meta_key'=>Health::REPORT,'orderby'=>'ID','order'=>'ASC'];if($id){$args['p']=$id;}
        $query=new \WP_Query($args);foreach($query->posts as$post){$report=get_post_meta($post->ID,Health::REPORT,true);if($report)self::report($post,$report);}
        if(!$query->posts){echo'<p>No page reports yet. Scan the website or use Check published SEO in a page’s SEO Health box.</p>';}
        echo wp_kses_post((string)paginate_links(['base'=>add_query_arg('paged','%#%',self::url($id)),'current'=>$paged,'total'=>$query->max_num_pages]));
        echo'<p>This is a bounded HTML and configuration audit, not a complete Google index, speed, accessibility or mobile test. Connect Search Console for Google’s indexed URL information. Results are snapshots; clear hosting cache if it serves older content.</p></div>';
        if(($job['status']??'')==='running'){wp_enqueue_script('open-seo-health',plugins_url('health-admin.js',__FILE__),['wp-api-fetch'],Suite::VERSION,true);wp_add_inline_script('open-seo-health','window.openSEOHealth='.wp_json_encode(['job'=>$job['id'],'url'=>self::url($id)]).';','before');}
    }
    public static function metabox($post){
        if(!current_user_can('edit_post',$post->ID))return;echo'<p><strong>SEO Health: check the published page, then fix what is safe.</strong></p>';
        $report=get_post_meta($post->ID,Health::REPORT,true);if($report){$totals=self::counts($report);echo'<p>'.esc_html($report['source']).' · '.$totals['review'].' reviews · '.$totals['unknown'].' unverified. <a href="'.esc_url(self::url($post->ID)).'">See issues and fixes</a></p>';}
        if(Health::allowed($post)&&current_user_can('manage_options')){echo'<p><button type="button" class="button button-primary" data-open-seo-health="scan" data-post="'.(int)$post->ID.'">Check published SEO</button> <button type="button" class="button" data-open-seo-health="fix" data-post="'.(int)$post->ID.'">Fix missing SEO fields</button></p><p id="open-seo-health-page-status" role="status" aria-live="polite">Checks use the saved, published page.</p><p><a href="'.esc_url(self::url($post->ID)).'">Open full SEO and AI readiness report</a></p>';}else{echo'<p>Publish the page to check its public HTML. Blank SEO fields still fill on save. Protected pages are not fetched.</p>';}
        echo'<p>GEO = AI search readiness: clear answers, accessible content and consistent facts. A perfect editor score is not required for Google or AI search.</p>';
    }
}
add_action('admin_menu',function(){add_submenu_page('rank-math','SEO Health & Fixes','SEO Health & Fixes','manage_options','open-seo-health',[HealthAdmin::class,'page'],1);},1002);
add_action('admin_post_open_seo_health',[HealthAdmin::class,'handle']);
add_action('add_meta_boxes',function(){foreach(['post','page']as$type){add_meta_box('open-seo-health','Open SEO · Check & fix',[HealthAdmin::class,'metabox'],$type,'normal','high');}});
add_action('admin_enqueue_scripts',function(){if(get_current_screen()&&get_current_screen()->base==='post'){wp_enqueue_script('open-seo-health',plugins_url('health-admin.js',__FILE__),['wp-api-fetch'],Suite::VERSION,true);}});

